def findFarmland(land: list[list[int]]) -> list[list[int]]:
    R, C = len(land), len(land[0])
    res = []
    for r in range(R):
        for c in range(C):
            if land[r][c] == 1:
                if (r > 0 and land[r - 1][c] == 1) or (c > 0 and land[r][c - 1] == 1):
                    continue
                r2, c2 = r, c
                while r2 + 1 < R and land[r2 + 1][c] == 1: r2 += 1
                while c2 + 1 < C and land[r][c2 + 1] == 1: c2 += 1
                res.append([r, c, r2, c2])
    return res

